/* ============================================
   TABLE COMPONENT
   Data table with flexible cell content
   ============================================ */

@layer rift.tokens, rift.preset, rift.components;

/* A frameless table's hover tile paints through these two, inside its
   cells' backgrounds and shadows. Registered as colours so the fill and
   the edge fade together; browsers without @property switch at once. */
@property --ds-table-fill {
  syntax: '<color>';
  initial-value: transparent;
  inherits: false;
}

@property --ds-table-edge {
  syntax: '<color>';
  initial-value: transparent;
  inherits: false;
}

@layer rift.components {

.ds-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  border-radius: var(--radius-200); /* 8px */

  /* Typography */
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  letter-spacing: var(--font-paragraph-letter-spacing);
  color: var(--color-text-primary);
}

/* The plain table clips its own rounded corners. The bordered table does
   not: its wrapper is the scroll container and clips for it, which leaves
   the table itself free of overflow so sticky headers and pinned columns can
   stick to the scrolling wrapper. */
.ds-table:not(.ds-table--bordered) {
  overflow: hidden;
}

/* ============================================
   CAPTION
   ============================================ */

.ds-table__caption {
  font-family: var(--font-paragraph-emphasis-family);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
  letter-spacing: var(--font-paragraph-emphasis-letter-spacing);
  color: var(--color-text-secondary);
  text-align: start;
  caption-side: top;
  padding-bottom: var(--padding-200); /* 8px */
}


/* ============================================
   ROW
   ============================================ */

.ds-table__row {
  border-bottom: var(--border-025) solid var(--color-table-divider);
  transition: background-color var(--motion-duration-base) var(--motion-ease-standard);
}

/* A row that heads a group, and a row the ones above add up to: both in
   the emphasis weight, the total under a heavier rule. */
.ds-table__row--heading .ds-table__cell,
.ds-table__row--total .ds-table__cell {
  font-weight: var(--font-paragraph-emphasis-weight);
}

/* The total's rule sits on its cells: with border-collapse: separate a
   row's own border never paints (the bordered variant's dividers below are
   on cells for the same reason). In the bordered table the row above drops
   its hairline, so the heavier rule is the only line between them. */
.ds-table__row--total .ds-table__cell {
  border-top: var(--border-050) solid var(--color-table-divider);
}

.ds-table--bordered .ds-table__row:has(+ .ds-table__row--total) .ds-table__cell {
  border-bottom: none;
}

/* ============================================
   HEADER CELL
   ============================================ */

.ds-table__header-cell {
  padding: var(--padding-200) var(--padding-400); /* 8px 16px */
  vertical-align: middle;

  /* paragraph-em (500 weight / label style) */
  font-family: var(--font-paragraph-emphasis-family);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
  letter-spacing: var(--font-paragraph-emphasis-letter-spacing);
  color: var(--color-text-secondary);
  text-align: start;
}

/* ============================================
   DATA CELL
   ============================================ */

.ds-table__cell {
  padding: var(--padding-200) var(--padding-400); /* 8px 16px */
  vertical-align: middle;
  color: var(--color-text-primary);
}

/* Inner wrapper ensures all cell content is perfectly vertically centred */
.ds-table__cell-content {
  display: flex;
  align-items: center;
  min-height: 0;
}

/* ============================================
   ROW HOVER (body rows only)
   ============================================ */

.ds-table__body .ds-table__row:hover {
  background-color: var(--color-table-row-hover-bg);
}

/* A row header is a <th scope="row"> for its semantics only: it is drawn as
   a data cell, without the browser's bold and centring. */
.ds-table__cell--row-header {
  font-weight: inherit;
  text-align: start;
}

/* ============================================
   STRIPED ROWS
   ============================================ */

.ds-table--striped .ds-table__body .ds-table__row:nth-child(even) {
  background-color: var(--color-table-row-stripe-bg);
}

.ds-table--striped .ds-table__body .ds-table__row:nth-child(even):hover {
  background-color: var(--color-table-row-hover-bg);
}

/* ============================================
   SIZE — DEFAULT (base styles apply)
   ============================================ */

.ds-table--default {
  /* Base padding & typography inherited from .ds-table */
}

/* ============================================
   BORDERED VARIANT
   Outer border box + tinted thead + divider row lines.
   Matches the table style used on markdown content pages.
   ============================================ */

/* The bordered table is a surface of its own: brighter than what it sits
   on in light, a little darker in dark, with an outline and a header band
   one step off the body. Its colours are the --color-table-* family, which
   every table reads. */
.ds-table__wrapper {
  overflow-x: auto;
  border: var(--border-025) solid var(--color-table-border);
  border-radius: var(--radius-300); /* 12px */
  background: var(--color-table-body-bg);
}

/* Columns never reflow on a phone: the wrapper scrolls instead
   (design.md's responsive contract). Natural column widths below the
   mobile breakpoint force the overflow the wrapper exists to catch —
   without this the table crushes to the viewport and cells clip. */
/* The plain table's scroll container: no surface of its own. */
.ds-table__scroll {
  overflow-x: auto;
  max-width: 100%;
}

@media (max-width: 768px) {
  .ds-table__scroll .ds-table,
  .ds-table__wrapper .ds-table {
    min-width: max-content;
  }
}

/* A bordered table's visible caption is drawn above the outline, where
   the plain table's sits: a <caption> would render inside the wrapper's
   border and scroll with it. The <caption> stays in the table, hidden, so
   the table and its scroll region keep their name. */
.ds-table__frame {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

/* When bordered, the table fills the wrapper — no radius needed on the table itself */
.ds-table--bordered {
  border-radius: 0;
}

/* Thead steps one notch off the body surface, so the header band reads as
   a header in both themes without a second border. */
.ds-table--bordered .ds-table__head {
  background: var(--color-table-header-bg);
}

/* Remove row-level border — border-collapse: separate ignores it */
.ds-table--bordered .ds-table__row {
  border-bottom: none;
}

/* Header cells: bottom divider */
.ds-table--bordered .ds-table__header-cell {
  border-bottom: var(--border-025) solid var(--color-table-divider);
}

/* Body cells: bottom divider */
.ds-table--bordered .ds-table__cell {
  border-bottom: var(--border-025) solid var(--color-table-divider);
}

/* Last body row: no bottom border (the wrapper border handles it) */
.ds-table--bordered .ds-table__body .ds-table__row:last-child .ds-table__cell {
  border-bottom: none;
}

/* Row hover on the bordered variant: the same table hover token as the
   plain table, a tint over whatever surface the body shows. */
.ds-table--bordered .ds-table__body .ds-table__row:hover {
  background-color: var(--color-table-row-hover-bg);
}

/* ============================================
   SIZE — COMPACT
   ============================================ */

.ds-table--compact .ds-table__header-cell {
  padding: var(--padding-150) var(--padding-300); /* 6px 12px */
  font-size: var(--font-paragraph-sm-size);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
}

.ds-table--compact .ds-table__cell {
  padding: var(--padding-150) var(--padding-300); /* 6px 12px */
  font-size: var(--font-paragraph-sm-size);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
}

/* ============================================
   SCREEN-READER-ONLY
   Fallback text for header cells with no visible
   label (checkbox / actions columns) — an empty
   <th> is unannounced.
   ============================================ */

/* ============================================
   SELECTED ROW
   Last in the file and as specific as the striped
   hover rule, so the selected tint holds over
   hover, stripe and the bordered hover alike.
   ============================================ */
.ds-table .ds-table__body .ds-table__row.ds-table__row--selected:nth-child(n) {
  background-color: var(--color-table-row-selected-bg);
}

/* ============================================
   COLUMN DIVIDERS
   A vertical line between columns, beside the
   lines between rows: for dense numeric tables
   that read down as well as across.
   ============================================ */
.ds-table--column-dividers .ds-table__header-cell:not(:last-child),
.ds-table--column-dividers .ds-table__cell:not(:last-child) {
  border-inline-end: var(--border-025) solid var(--color-table-divider);
}

/* ============================================
   CODE COLUMN (column `mono`)
   A reference table's code cells: the code face at the
   cell's size, broken anywhere so a long type wraps inside
   its column rather than widening the table.
   ============================================ */

.ds-table__cell-content--mono {
  font-family: var(--font-family-code);
  font-size-adjust: var(--font-code-aspect);
  overflow-wrap: anywhere;
  word-break: break-word;
}

/* ============================================
   FRAMELESS AND THE OUTER CONTROL: wider than a phone only
   Below the phone step a frameless table is drawn as the plain table is,
   and the outer control's column as an ordinary first column: a phone has
   no hover to reveal the control and no page margin for the tile's reach.
   DataTable makes the same switch at its own width, so a table in a narrow
   panel counts there too.
   ============================================ */

@media (min-width: 601px) {
  /* ============================================
     FRAMELESS (`frameless`)
     No outline, no header band, no column dividers, no table surface: the
     lines between rows stay, cut to the content. The first and last
     columns' content sits flush with the page: the scroll container reaches
     past its column by the bleed (--padding-400) on both sides and the end
     cells pad back in by it. A hovered row lifts into a raised tile that
     fills that reach.

     The tile is painted by the cells, never by a shape behind the row, so a
     sticky cell (DataTable's pinned columns and sticky header) paints its own
     part of it. Each cell stacks a base (opaque only where it sticks), the
     row's fill, and its divider along the foot. The tile's edges are shadows
     that take no room, in the divider's colour, on the very pixels the
     dividers use: the top edge on the line above, the bottom edge on the
     row's own line. Where the tile meets a divider that line never changes,
     so the tile fades in without a second line ever showing.

     Two override hooks: --ds-table-tile, the tile's fill (the raised
     container surface by default, which keeps a control in the row hovering
     with the contrast it has on a card), and --ds-table-surface, what a
     sticky cell and the seam between selected rows are painted with (the
     page by default; a table on a card sets it to the card's colour).
     ============================================ */

  .ds-table.ds-table--frameless {
    --ds-table-bleed: var(--padding-400);
    --ds-table-radius: var(--radius-300);

    overflow: visible;
    border-radius: 0;
  }

  .ds-table.ds-table--frameless.ds-table--compact {
    --ds-table-radius: var(--radius-200);
  }

  /* The scroll container reaches out by the bleed. */
  .ds-table__scroll--frameless {
    margin-inline: calc(-1 * var(--padding-400));
    max-width: none;
  }

  .ds-table--frameless .ds-table__head {
    background: transparent;
  }

  .ds-table--frameless .ds-table__caption {
    padding-inline: var(--padding-400);
  }

  /* Rows paint nothing; their cells paint the tile. */
  .ds-table--frameless .ds-table__body .ds-table__row,
  .ds-table--frameless .ds-table__body .ds-table__row:hover,
  .ds-table.ds-table--frameless.ds-table--striped .ds-table__body .ds-table__row:nth-child(even),
  .ds-table.ds-table--frameless .ds-table__body .ds-table__row.ds-table__row--selected:nth-child(n) {
    background-color: transparent;
  }

  .ds-table--frameless :is(.ds-table__cell, .ds-table__header-cell) {
    --ds-table-line: var(--color-table-divider);
    --ds-table-fill: transparent;
    --ds-table-edge: transparent;
    --ds-table-line-size: 100%;
    --ds-table-line-at: bottom;
    --ds-table-side: 0 0 transparent;

    border: 0;
    box-shadow:
      0 calc(-1 * var(--border-025)) 0 0 var(--ds-table-edge),
      inset 0 calc(-1 * var(--border-025)) 0 0 var(--ds-table-edge),
      var(--ds-table-side);
    background-color: var(--ds-table-base, transparent);
    background-image:
      linear-gradient(var(--ds-table-line), var(--ds-table-line)),
      linear-gradient(var(--ds-table-fill), var(--ds-table-fill));
    background-size:
      var(--ds-table-line-size) var(--border-025),
      100% 100%;
    background-position:
      var(--ds-table-line-at),
      0 0;
    background-repeat: no-repeat;
    transition:
      --ds-table-fill var(--motion-duration-fast) var(--motion-ease-standard),
      --ds-table-edge var(--motion-duration-fast) var(--motion-ease-standard);
  }

  /* The end cells pad in by the bleed, round the tile's corners and draw
     its side edge; their stretch of divider stops at the content. */
  .ds-table--frameless .ds-table__row > :first-child {
    --ds-table-side: inset var(--border-025) 0 0 0 var(--ds-table-edge); /* ds-allow(physical): the start side; flipped for rtl below */
    --ds-table-line-size: calc(100% - var(--ds-table-bleed));
    --ds-table-line-at: bottom right; /* ds-allow(physical): the divider is cut at the start side; flipped for rtl below */

    padding-inline-start: var(--ds-table-bleed);
    border-start-start-radius: var(--ds-table-radius);
    border-end-start-radius: var(--ds-table-radius);
  }

  .ds-table--frameless .ds-table__row > :last-child {
    --ds-table-side: inset calc(-1 * var(--border-025)) 0 0 0 var(--ds-table-edge); /* ds-allow(physical): the end side; flipped for rtl below */
    --ds-table-line-size: calc(100% - var(--ds-table-bleed));
    --ds-table-line-at: bottom left; /* ds-allow(physical): the divider is cut at the end side; flipped for rtl below */

    padding-inline-end: var(--ds-table-bleed);
    border-start-end-radius: var(--ds-table-radius);
    border-end-end-radius: var(--ds-table-radius);
  }

  .ds-table--frameless:dir(rtl) .ds-table__row > :first-child {
    --ds-table-side: inset calc(-1 * var(--border-025)) 0 0 0 var(--ds-table-edge);
    --ds-table-line-at: bottom left; /* ds-allow(physical): the start side in rtl */
  }

  .ds-table--frameless:dir(rtl) .ds-table__row > :last-child {
    --ds-table-side: inset var(--border-025) 0 0 0 var(--ds-table-edge);
    --ds-table-line-at: bottom right; /* ds-allow(physical): the end side in rtl */
  }

  /* The header's line hides when the first row is selected. Kept apart
     from the body's line rules on purpose: a bundler merges adjacent rules
     with the same body into one :is() list, and an :is() takes its heaviest
     argument's specificity, which would carry the simple row rule past the
     seam rule below. */
  .ds-table.ds-table--frameless:has(.ds-table__body .ds-table__row--selected:first-child) .ds-table__header-cell {
    --ds-table-line: transparent;
  }

  /* A total row keeps its heavier rule, and the line above it gives way so
     the two never stack. */
  .ds-table.ds-table--frameless .ds-table__body .ds-table__row--total > .ds-table__cell {
    border-top: var(--border-050) solid var(--color-table-divider);
  }

  .ds-table.ds-table--frameless .ds-table__body .ds-table__row:has(+ .ds-table__row--total) > .ds-table__cell {
    --ds-table-line: transparent;
  }

  /* The last body row has no line under it: the table simply ends. */
  .ds-table--frameless .ds-table__body:last-of-type .ds-table__row:last-child > * {
    --ds-table-line: transparent;
  }

  /* A tint with no edge (stripe, selection) covers its own line. Striped,
     hovered and selected share a weight, so the later one wins: selected
     over hovered over striped. */
  .ds-table.ds-table--frameless.ds-table--striped .ds-table__body .ds-table__row:nth-child(even) > * {
    --ds-table-fill: var(--color-table-row-stripe-bg);
    --ds-table-line: transparent;
  }

  /* The tile, on hover and on keyboard focus inside the row. */
  .ds-table.ds-table--frameless .ds-table__body .ds-table__row:is(:hover, :has(:focus-visible)) > * {
    --ds-table-fill: var(--ds-table-tile, var(--color-bg-container-primary));
    --ds-table-edge: var(--color-table-divider);
  }

  .ds-table.ds-table--frameless .ds-table__body .ds-table__row.ds-table__row--selected > * {
    --ds-table-fill: var(--color-table-row-selected-bg);
    --ds-table-line: transparent;
  }

  /* The line above a selected row hides too. */
  .ds-table.ds-table--frameless .ds-table__body .ds-table__row:has(+ .ds-table__row--selected) > * {
    --ds-table-line: transparent;
  }

  /* Between two selected rows the line is a seam in the surface colour,
     straight across the whole row: the selected tint and the divider are a
     step apart at most, so a divider in its own colour would vanish and a
     block of selected rows would read as one slab. Where they meet, their
     corners square off, so the block is one rounded shape. */
  .ds-table.ds-table--frameless .ds-table__body .ds-table__row.ds-table__row--selected:has(+ .ds-table__row--selected) > * {
    --ds-table-line: var(--ds-table-surface, var(--color-bg-page-primary));
    --ds-table-line-size: 100%;
    --ds-table-line-at: bottom;
  }

  .ds-table.ds-table--frameless .ds-table__body .ds-table__row.ds-table__row--selected:has(+ .ds-table__row--selected) > :first-child {
    border-end-start-radius: 0;
  }

  .ds-table.ds-table--frameless .ds-table__body .ds-table__row.ds-table__row--selected:has(+ .ds-table__row--selected) > :last-child {
    border-end-end-radius: 0;
  }

  .ds-table.ds-table--frameless .ds-table__body .ds-table__row.ds-table__row--selected + .ds-table__row--selected > :first-child {
    border-start-start-radius: 0;
  }

  .ds-table.ds-table--frameless .ds-table__body .ds-table__row.ds-table__row--selected + .ds-table__row--selected > :last-child {
    border-start-end-radius: 0;
  }

  /* ============================================
     OUTER CONTROL (`outerControl`)
     The first column is a 40px control column (a grip, a checkbox) that
     takes the place of the start bleed: the scroll container reaches out by
     its width instead, the control sits inside the tile's start, and the
     next cell drops its bleed so the content still lines up with the page.
     The control shows on hover, on keyboard focus, when checked, while any
     row is selected, and always where there is no hover to reveal it.
     40px is DataTable's utility column width (UTILITY_COLUMN_WIDTH).
     ============================================ */

  .ds-table__scroll--outer-control {
    margin-inline-start: -40px; /* ds-allow(spacing): the outer control column, DataTable's UTILITY_COLUMN_WIDTH */
  }

  .ds-table--outer-control .ds-table__caption {
    padding-inline-start: 40px; /* ds-allow(spacing): the outer control column */
  }

  /* The control's cell starts the tile: corners and side edge, but no
     bleed and no stretch of divider (a seam between selected rows still
     crosses it). */
  .ds-table.ds-table--outer-control .ds-table__row > :first-child {
    --ds-table-line: transparent;

    width: 40px; /* ds-allow(spacing): the outer control column */
    padding-inline: 0;
    text-align: center;
  }

  /* An auto-laid-out table squeezes a cell to its content's minimum, so the
     column's width is held by its content too. */
  .ds-table--outer-control .ds-table__row > :first-child > .ds-table__cell-content {
    min-width: 40px; /* ds-allow(spacing): the outer control column */
    justify-content: center;
  }

  .ds-table--outer-control .ds-table__row > :first-child > * {
    opacity: 0;
    transition: opacity var(--motion-duration-fast) var(--motion-ease-standard);
  }

  .ds-table--outer-control .ds-table__body .ds-table__row:is(:hover, :has(:focus-visible), .ds-table__row--selected) > :first-child > *,
  .ds-table--outer-control .ds-table__row > :first-child:has(:focus-visible, :checked, [aria-checked="true"], [aria-checked="mixed"]) > *,
  .ds-table--outer-control:is(:hover, [data-selecting], :has(.ds-table__body :is(:checked, [aria-checked="true"]))) .ds-table__head .ds-table__row > :first-child > *,
  .ds-table--outer-control:is([data-selecting], :has(.ds-table__body :is(:checked, [aria-checked="true"]))) .ds-table__body .ds-table__row > :first-child > * {
    opacity: 1;
  }

  @media (hover: none) {
    .ds-table--outer-control .ds-table__row > :first-child > * {
      opacity: 1;
    }
  }

  /* The cell after the control: no bleed, no corner, no side edge, and a
     divider across its full width, starting at the content. */
  .ds-table.ds-table--outer-control .ds-table__row > :first-child + * {
    --ds-table-side: 0 0 transparent;
    --ds-table-line-size: 100%;
    --ds-table-line-at: bottom;

    padding-inline-start: 0;
    border-start-start-radius: 0;
    border-end-start-radius: 0;
  }

  /* Forced colours drop shadows and fills, so the tile and the selection
     are outlined in system colours instead. */
  @media (forced-colors: active) {
    .ds-table--frameless .ds-table__body .ds-table__row:is(:hover, :has(:focus-visible)) {
      outline: var(--border-025) solid CanvasText;
      outline-offset: calc(-1 * var(--border-025));
    }

    .ds-table--frameless .ds-table__body .ds-table__row.ds-table__row--selected {
      outline: var(--border-025) solid Highlight;
      outline-offset: calc(-1 * var(--border-025));
    }
  }
}

} /* @layer rift.components */

// No 'use client' directive: Table is purely presentational — no hooks, no event
// handlers — so it stays renderable from a React Server Component. The one
// measured part, the bordered wrapper's ScrollRegion, is a client boundary of
// its own.

import React from 'react';
import './Table.css';
import { ScrollRegion } from '../../behaviors/ScrollRegion';
import '../../behaviors/visually-hidden.css';
import { warnOnce } from '../../behaviors/devWarning';

export interface TableColumn {
  /** Unique column identifier, used as the key into each row's cells */
  key: string;
  /** Header label displayed in the column header */
  header: React.ReactNode;
  /** Optional column width (CSS value like '200px', '30%', 'auto') */
  width?: string;
  /** Text alignment for cells in this column. `start` (the default) and `end` follow the reading direction, so a number column set to `end` sits right in English and left in Arabic; `left` and `right` are screen sides. */
  align?: 'start' | 'center' | 'end' | 'left' | 'right';
  /** The column's current sort, the direction DataTable's sorts use, set as `aria-sort` on its header so a screen reader announces it while reading the column. Leave unset on unsorted columns. */
  sort?: 'asc' | 'desc';
  /** Whether this column names each row. Its cells render as row headers (`<th scope="row">`), so moving along a row announces which record it is. */
  rowHeader?: boolean;
  /** Set the column's cells in the code face, wrapping long values at any character: for prop names, types, defaults, tokens and other code a reference table lists. */
  mono?: boolean;
}

export interface TableRow {
  /** Unique row identifier */
  id: string;
  /** Cell values keyed by column key — each accepts any React node */
  cells: Record<string, React.ReactNode>;
  /** Whether the row is selected, drawn with the table's selected-row tint. */
  selected?: boolean;
  /** `heading` opens a group of rows in the emphasis weight; `total` is a row the ones above add up to, in the emphasis weight under a heavier rule. */
  variant?: 'default' | 'heading' | 'total';
}

/** Props owned by Table itself — everything else falls through to the <table>. */
type TableOwnProps = {
  /** Column definitions */
  columns: TableColumn[];
  /** Row data */
  rows: TableRow[];
  /** Visual size */
  size?: 'default' | 'compact';
  /** Alternating row background colours */
  striped?: boolean;
  /**
   * Adds an outer border + border-radius container, a tinted thead background,
   * and `--color-divider` row lines — matching the bordered table style used on
   * markdown content pages. `frameless` wins when both are set.
   */
  bordered?: boolean;
  /** Draws a vertical line between columns, as well as the lines between rows. A frameless table draws none. */
  columnDividers?: boolean;
  /**
   * Draws the table with no frame: no outline, no header band and no column
   * dividers, the first and last columns' content flush with the page, and
   * a hovered row lifted into a raised tile that reaches past the columns.
   * The page needs room for that reach on both sides (`--padding-400`).
   * Wins over `bordered`. On a phone (a viewport under `BREAKPOINT_PHONE_PX`)
   * it is drawn as the plain table, the outer control as an ordinary column.
   */
  frameless?: boolean;
  /**
   * With `frameless`, makes the first column the row's outer control: a
   * 40px column, its content centred, that sits inside the tile's start and
   * shows on hover, on keyboard focus, when checked, or while any row is
   * checked. Put a drag grip or a checkbox in it. The page needs 40px of
   * room on the table's start side for it. Leave at least one other column
   * without a width: when every column has one, the browser stretches them
   * all, the control's with them.
   */
  outerControl?: boolean;
  /** Accessible caption for the table */
  caption?: string;
  /** Whether to visually hide the caption (still available to screen readers) */
  captionHidden?: boolean;
  /** Additional CSS classes */
  className?: string;
};

export interface TableProps
  extends TableOwnProps,
    Omit<React.ComponentPropsWithoutRef<'table'>, keyof TableOwnProps> {}

/**
 * Table component from Figma design system.
 * Data table with flexible cell content — supports text, icons,
 * inputs, buttons, and any other React nodes inside cells.
 *
 * Forwards a ref to the `<table>` element and spreads unrecognised props onto
 * it. When `bordered`, the table is wrapped in a container div — the ref and
 * spread props still target the inner `<table>`.
 */
export const Table = React.forwardRef<HTMLTableElement, TableProps>(
  (
    {
      columns,
      rows,
      size = 'default',
      striped = false,
      bordered = false,
      columnDividers = false,
      frameless = false,
      outerControl = false,
      caption,
      captionHidden = false,
      className = '',
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-table';
    if (frameless && bordered) warnOnce('Table: `frameless` and `bordered` both set; frameless wins.');
    const framed = bordered && !frameless;
    const outer = frameless && outerControl;
    // The outer control's column is centred whatever the column says.
    const alignOf = (col: TableColumn, index: number) => (outer && index === 0 ? 'center' : col.align);

    const classes = [
      baseClass,
      `${baseClass}--${size}`,
      striped ? `${baseClass}--striped` : '',
      framed ? `${baseClass}--bordered` : '',
      columnDividers && !frameless ? `${baseClass}--column-dividers` : '',
      frameless ? `${baseClass}--frameless` : '',
      outer ? `${baseClass}--outer-control` : '',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    // A bordered table draws its visible caption outside the outline (see
    // the frame rule in Table.css), so the <caption> itself is hidden.
    const outsideCaption = framed && caption && !captionHidden;

    const table = (
      <table {...rest} ref={ref} className={classes}>
        {caption && (
          <caption
            className={
              captionHidden || outsideCaption ? `${baseClass}__caption ds-visually-hidden` : `${baseClass}__caption`
            }
          >
            {caption}
          </caption>
        )}

        <thead className={`${baseClass}__head`}>
          <tr className={`${baseClass}__row ${baseClass}__row--header`}>
            {columns.map((col, index) => (
              <th
                key={col.key}
                className={`${baseClass}__header-cell`}
                scope="col"
                aria-sort={col.sort === 'asc' ? 'ascending' : col.sort === 'desc' ? 'descending' : undefined}
                style={{
                  width: col.width,
                  textAlign: alignOf(col, index) || 'start',
                }}
              >
                {/* An empty header cell is unannounced — fall back to the
                    column key so the column is still identifiable. */}
                {col.header || <span className="ds-visually-hidden">{col.key}</span>}
              </th>
            ))}
          </tr>
        </thead>

        <tbody className={`${baseClass}__body`}>
          {rows.map((row) => (
            <tr
              key={row.id}
              className={[
                `${baseClass}__row`,
                row.selected ? `${baseClass}__row--selected` : '',
                row.variant && row.variant !== 'default' ? `${baseClass}__row--${row.variant}` : '',
              ]
                .filter(Boolean)
                .join(' ')}
            >
              {columns.map((col, index) => {
                const align = alignOf(col, index);
                const content = (
                  <div
                    className={`${baseClass}__cell-content${col.mono ? ` ${baseClass}__cell-content--mono` : ''}`}
                    style={{
                      // flex-start and flex-end follow the reading direction;
                      // left and right stay on their screen side.
                      justifyContent:
                        align === 'center'
                          ? 'center'
                          : align === 'end'
                            ? 'flex-end'
                            : align === 'left' || align === 'right'
                              ? align
                              : 'flex-start',
                    }}
                  >
                    {row.cells[col.key]}
                  </div>
                );
                return col.rowHeader ? (
                  <th key={col.key} className={`${baseClass}__cell ${baseClass}__cell--row-header`} scope="row">
                    {content}
                  </th>
                ) : (
                  <td key={col.key} className={`${baseClass}__cell`}>
                    {content}
                  </td>
                );
              })}
            </tr>
          ))}
        </tbody>
      </table>
    );

    // The bordered wrapper is the table's scroll container: a named,
    // focusable region while it overflows, a plain div while it fits.
    if (framed) {
      const region = <ScrollRegion className={`${baseClass}__wrapper`}>{table}</ScrollRegion>;
      if (!outsideCaption) return region;
      return (
        <div className={`${baseClass}__frame`}>
          <div className={`${baseClass}__caption`} aria-hidden="true">
            {caption}
          </div>
          {region}
        </div>
      );
    }

    // The plain table scrolls in a borderless container of its own, the
    // same region as the bordered one, so a wide table scrolls inside its
    // column rather than running off the page.
    // A frameless table's scroll container reaches past its column by the
    // tile's bleed (and the outer control's width) so the tile has room.
    const scrollClasses = [
      `${baseClass}__scroll`,
      frameless ? `${baseClass}__scroll--frameless` : '',
      outer ? `${baseClass}__scroll--outer-control` : '',
    ]
      .filter(Boolean)
      .join(' ');
    return <ScrollRegion className={scrollClasses}>{table}</ScrollRegion>;
  },
);

Table.displayName = 'Table';
